        'slack_copy_manifest' => 'ম্যানিফেস্ট কপি করুন',
        'slack_scopes_heading' => 'অ্যাপটিকে কী করার অনুমতি দেওয়া আছে',
        'slack_scopes_desc' => 'অ্যাপ অনুমোদনের সময় আপনার Slack অ্যাডমিন এই তালিকা দেখবেন। এখানকার কিছুই এটিকে চ্যানেল তৈরি করতে, মানুষকে আমন্ত্রণ জানাতে বা আমন্ত্রণ না পাওয়া কোথাও পোস্ট করতে দেয় না।',
        'slack_step1' => 'Slack-এ <strong>api.slack.com/apps</strong>-এ যান এবং <strong>Create New App → From a manifest</strong> বেছে নিন। সার্ভিস ডেস্কটি যে ওয়ার্কস্পেসে চান সেটি নির্বাচন করুন।',
        'slack_step2' => 'এই ম্যানিফেস্টটি পেস্ট করুন। এটি নাম, অনুমতি এবং Slack যে ঠিকানায় বার্তা পাঠায় তা সেট করে, তাই হাতে টিক দেওয়ার কিছু নেই।',
        'slack_step3' => '<strong>Install to Workspace</strong> ক্লিক করে অনুমোদন করুন। তারপর <strong>Bot User OAuth Token</strong> ও <strong>Signing Secret</strong> কপি করে এখানকার সম্পাদনা ফর্মে ফিরিয়ে দিন — Slack টোকেনটি আর দেখাবে না। <strong>Slack যদি হলুদ &ldquo;Reinstall to Workspace&rdquo; ব্যানার দেখায়, আগে সেটিতে ক্লিক করুন</strong> — নইলে টোকেনের বেশিরভাগ অনুমতি থাকবে না এবং টিকিট প্রেরকের নাম ছাড়াই আসবে।',
        'slack_step4' => 'নিচের রিকোয়েস্ট URL-টি Slack-এর <strong>Event Subscriptions</strong>-এ যা দেখায় তার সাথে মেলে কিনা দেখুন। অ্যাপ সংরক্ষণের মুহূর্তেই Slack এটি যাচাই করে, তাই এই সার্ভারকে ইন্টারনেট থেকে পৌঁছানো যেতে হবে।',
        'slack_step5' => 'Slack-এ, অ্যাপটি যে চ্যানেল নজরে রাখবে সেখানে তাকে আমন্ত্রণ জানান: <strong>/invite @YourApp</strong>। যে চ্যানেলে এটি নেই তা এটি পড়তে পারে না।',
    ],
