        'old_image_body' => 'আগে FreeITSM-এর সর্বশেষ ইমেজে আপডেট করুন, তারপর এই পেজে ফিরে আসুন। সোর্স থেকে বিল্ড করলে FreeITSM ফোল্ডারে {cmd} চালান।',
        'proxy_note' => 'এই কন্টেইনার একটি রিভার্স প্রক্সির পেছনে সেট আপ করা আছে (TRUST_PROXY_HTTPS চালু)। সাধারণত প্রক্সিই HTTPS সামলায়, তাই সম্ভবত এই পেজের প্রয়োজন নেই।',
        'not_persisted_title' => 'আগে আপনার Docker সেটআপে একটি পরিবর্তন করুন',
        'not_persisted_body' => 'সার্টিফিকেট নিরাপদে রাখার মতো কোনো জায়গা এই কন্টেইনারে নেই: পরের আপডেটে সেটি মুছে যাবে। যে ফোল্ডারে আপনার docker-compose.yml আছে সেখানে {file} নামে একটি ফাইল তৈরি করুন এবং নিচের লেখাটি তাতে দিন। ফাইলটি আগে থেকে থাকলে এই লাইনগুলো তাতে যোগ করুন।',
        'not_persisted_then' => 'তারপর একই ফোল্ডারে {cmd} চালান এবং এই পেজটি রিলোড করুন।',
        'status_off_title' => 'HTTPS বন্ধ আছে',
        'status_off_body' => 'FreeITSM শুধু সাধারণ HTTP-তে পাওয়া যাচ্ছে। HTTPS চালু করতে নিচে একটি সার্টিফিকেট তৈরি করুন।',
        'status_on_title' => 'HTTPS চালু আছে',
