        'caldav_no_notify' => 'CalDAV সার্ভার পরিবর্তনের বিজ্ঞপ্তি পাঠায় না, তাই ক্যালেন্ডারে করা পরিবর্তন নির্ধারিত জব চলার সময় আসে।',
        'people_desc_caldav' => 'প্রতিটি বিশ্লেষক CalDAV সার্ভারে সাইন ইন করে পছন্দসমূহে নিজের ক্যালেন্ডার বেছে নেন। অ্যাডমিনিস্ট্রেটর তাঁদের হয়ে এটি বাছতে পারেন না, কারণ ক্যালেন্ডারে পৌঁছানোর পাসওয়ার্ড শুধু বিশ্লেষকের কাছেই আছে।',
