        'switch_confirm' => 'এতে এই সংযোগ বিশ্লেষকদের ক্যালেন্ডারে যে {mapped}টি ইভেন্ট রেখেছে তা ফিরিয়ে নেওয়া হবে, এবং এটি ব্যবহারকারী {pushing} জন বিশ্লেষকের ক্যালেন্ডার সিঙ্ক বন্ধ হবে, যাতে প্রত্যেকে আবার সেট আপ করতে পারেন। অন্য সংযোগের বিশ্লেষক এবং সাবস্ক্রিপশন লিঙ্ক প্রভাবিত হবে না।',
        'switch_ok' => 'পরিবর্তন',
        'switch_done' => 'সংরক্ষিত হয়েছে। এই সংযোগের বিশ্লেষকদের ক্যালেন্ডার সিঙ্ক রিসেট করা হয়েছে।',
        'perm_title' => 'এটি কাজ করার আগে',
        'perm_body' => 'অ্যাপ রেজিস্ট্রেশনে <strong>Application</strong> পারমিশন হিসেবে <strong>Calendars.ReadWrite</strong> লাগবে (Delegated নয় — Azure-এ এ দুটি আলাদা তালিকা), এবং অ্যাডমিন কনসেন্ট দেওয়া থাকতে হবে। মনে রাখবেন, এই পারমিশনে FreeITSM <strong>টেন্যান্টের প্রতিটি মেইলবক্সে</strong> লিখতে পারে। এটি আপনার চাওয়ার চেয়ে বেশি হলে Exchange Online-এ Application Access Policy ব্যবহার করে অ্যাপটিকে আপনার বিশ্লেষকদের একটি মেইল-সক্ষম সিকিউরিটি গ্রুপে সীমাবদ্ধ করুন।',
        'name' => 'নাম',
        'source_mailbox' => 'একটি মেইলবক্স থেকে ক্রেডেনশিয়াল ধার নিন',
        'source_own' => 'ক্রেডেনশিয়াল লিখুন',
        'mailbox' => 'মেইলবক্স',
        'no_mailboxes' => 'এই সিস্টেমের কোনো Microsoft মেইলবক্সে ধার নেওয়ার মতো Azure ক্রেডেনশিয়াল নেই, তাই নিচে সেগুলো লিখুন। আপনার বিশ্লেষকদের ক্যালেন্ডার ইনটেক মেইলবক্সের চেয়ে আলাদা টেন্যান্টে থাকলে, বা ইনটেক Microsoft-এর না হলে, এটি স্বাভাবিক।',
