        'conn_deleted' => 'সংযোগ মুছে ফেলা হয়েছে',
        'people_heading' => 'প্রতিটি বিশ্লেষক কোন মেইলবক্সে সিঙ্ক করেন',
        'people_desc' => 'ডিফল্টভাবে FreeITSM বিশ্লেষকের&rsquo; অ্যাকাউন্টের ইমেল ঠিকানা ব্যবহার করে, যা প্রায়ই তাঁর মেইলবক্স নয় &mdash; যেমন লোকাল অ্যাকাউন্ট, বা অন্য কিছুর ভিত্তিতে ডিরেক্টরি ইমপোর্ট। এখানে সেটি বদলান। বিশ্লেষকরা ঠিক করেন তাঁদের কাজ সিঙ্ক হবে <em>কিনা</em>; কাজ <em>কোথায়</em> যাবে তা শুধু অ্যাডমিনিস্ট্রেটর ঠিক করেন।',
