        'saved_unverified' => 'সংরক্ষিত হয়েছে। সংযোগ কাজ না করায় ঠিকানাটি যাচাই করা যায়নি — উপরে এটি পরীক্ষা করুন।',
        'inbound_heading' => 'ক্যালেন্ডারে করা পরিবর্তন',
        'inbound_desc' => 'Outlook-এ এই অ্যাপয়েন্টমেন্টগুলোর কোনোটি সরালে টিকিটও সেই অনুযায়ী বদলায়। এর জন্য <code>cron/calendar_sync_pull.php</code> জব চালু থাকতে হবে &mdash; প্রতি ৫ মিনিটে চালানো যুক্তিসংগত। এটি ছাড়া সিঙ্ক একমুখী থাকে, আজ যেমন কাজ করে ঠিক তেমনই।',
        'accept_deletes' => 'অ্যাপয়েন্টমেন্ট মুছলে টিকিটের সময়সূচি বাতিল হবে',
        'notify_url' => 'বিজ্ঞপ্তি URL (ঐচ্ছিক)',
        'notify_url_note' => 'শুধু নির্ধারিত যাচাইয়ের ওপর নির্ভর করতে ফাঁকা রাখুন, যা সম্পূর্ণ ঠিকঠাক &mdash; তখন পরিবর্তন কয়েক মিনিটের মধ্যে আসে। এটি পূরণ করলে কিছু বদলানোর মুহূর্তেই Microsoft FreeITSM-কে জানাবে, ফলে তা কয়েক সেকেন্ডে পৌঁছায়। এটি অবশ্যই এমন একটি <strong>HTTPS ঠিকানা হতে হবে যেখানে Microsoft ইন্টারনেট থেকে পৌঁছাতে পারে</strong>, যার শেষে <code>/api/calendar/graph_notify.php</code>। নির্ধারিত জব দুই ক্ষেত্রেই লাগবে: এটি সাবস্ক্রিপশন নবায়ন করে, আর কোনো বিজ্ঞপ্তি মিস হলে যা হারাত তা ধরে ফেলে।',
        'notify_suggest' => 'এই ঠিকানা ব্যবহার করুন',
        'notify_suggest_note' => 'আপনি এখন যে ঠিকানা ব্যবহার করছেন তা থেকে পূরণ করা হয়েছে। বাইরে থেকে এতে পৌঁছানো যায় কিনা দেখুন — প্রক্সি বা টানেলের পেছনে প্রায়ই যায় না, আর ভুল ঠিকানা ঠিকানা নিয়ে নয়, যাচাই নিয়ে একটি বার্তা দিয়ে ব্যর্থ হয়।',
