        'accept_deletes_note' => 'ডিফল্টভাবে বন্ধ। চালু থাকলে, কোনো বিশ্লেষক ফোনে এগুলোর একটি মুছলে ডেস্কে বসেই দেখেন টিকিটের সময়সূচি আগেই বাতিল হয়ে গেছে &mdash; যা প্রায়ই উদ্দেশ্য। এমন প্রতিটি পরিবর্তন টিকিটের&rsquo; ইতিহাসে লেখা হয়, এবং একসাথে অস্বাভাবিক বেশি মুছে ফেলা হলে তা মানা হয় না, বাতিল করা হয়, কারণ সেটি নির্দেশের চেয়ে ত্রুটি হওয়ার সম্ভাবনাই বেশি। বন্ধ থাকলে, মুছে ফেলা অ্যাপয়েন্টমেন্ট টিকিট পরের বার বদলালে আবার দেখা দেয়।',
