        'desktop_blocked' => 'আপনার ব্রাউজার এই সাইট থেকে বিজ্ঞপ্তি আটকে দিচ্ছে। ব্রাউজারের সাইট সেটিংসে (ঠিকানার পাশের তালার চিহ্ন) এগুলো অনুমোদন করুন, তারপর এটি চালু করুন।',
