        'carddav_book_untested' => 'আপনার অ্যাড্রেস বুক দেখতে সংযোগ পরীক্ষা চাপুন',
        'carddav_book_required' => 'একটি অ্যাড্রেস বুক বেছে নিন। তালিকা দেখতে আগে সংযোগ পরীক্ষা চাপুন।',
