        'carddav_test' => 'সংযোগ পরীক্ষা',
        'carddav_test_desc' => 'FreeITSM সার্ভারে পৌঁছাতে ও সাইন ইন করতে পারে কিনা যাচাই করে, এবং যেসব অ্যাড্রেস বুক দেখা যায় তার তালিকা দেয়।',
        'carddav_test_desc_create' => 'FreeITSM এই তথ্য দিয়ে সার্ভারে পৌঁছাতে ও সাইন ইন করতে পারে কিনা যাচাই করে।',
