        'carddav_write_hint' => 'সাধারণত FreeITSM এই অ্যাড্রেস বুক শুধু পড়ে। এটি চালু করলে কোনো বিশ্লেষক কন্ট্যাক্টের পদবি, বিভাগ, অফিস, ফোন বা মোবাইলে যে পরিবর্তন করেন তা তাদের কার্ডেও লেখা হয়। তাদের কর্মী আইডি ও ম্যানেজার FreeITSM-এই থাকে, কারণ কন্ট্যাক্ট কার্ডে সেগুলো রাখার জায়গা নেই।',
        'carddav_write_back' => 'FreeITSM-এ করা পরিবর্তন অ্যাড্রেস বুকে ফেরত লিখুন',
        'carddav_allow_create' => 'বিশ্লেষকদের এই অ্যাড্রেস বুকে মানুষ যোগ করতে দিন',
        'carddav_allow_create_hint' => 'ডিফল্টভাবে বন্ধ। চালু থাকলে, কোনো অ্যাড্রেস বুকে নেই এমন ব্যক্তির জন্য Tickets ও Assets-এ একটি "অ্যাড্রেস বুকে যোগ" বোতাম আসে, যা এখানে তার কার্ড তৈরি করে ও তাকে লিঙ্ক করে। কিছু লেখার আগে FreeITSM দেখে নেয় বইয়ে আর কারও এই ইমেল ঠিকানা নেই, এবং পরে দেখে নতুন কার্ডটি এই সোর্স যা আমদানি করে তার মধ্যে পড়ে কিনা - যে ট্যাগ বা গ্রুপ দিয়ে আমদানি হয় তা যোগ করে - আর না পড়লে সেটি আবার সরিয়ে দেয়।',
        'carddav_write_warning' => 'শুধু উপরে তালিকাভুক্ত তথ্যগুলো বদলানো হয়, এবং শুধু যে কন্ট্যাক্টটি সম্পাদনা করা হচ্ছে তার। কার্ডের বাকি সবকিছু — ছবি, নোট, জন্মদিন, পূর্ণ ঠিকানা, গ্রুপ — ঠিক যেমন আছে তেমনই থাকে। FreeITSM সর্বশেষ আমদানি করার পর কেউ অ্যাড্রেস বুকে একই তথ্য বদলে থাকলে, তাদের পরিবর্তন ওভাররাইট না করে আপনার পরিবর্তনটি প্রত্যাখ্যান করা হয়।',
        'carddav_write_check' => 'অনুমতি যাচাই',
