        'enc_on_body' => 'ওয়ার্কফ্লো এবং ডেলিভারি কিউ - দুই জায়গাতেই AES-256-GCM দিয়ে সংরক্ষিত। একটি ওয়েবহুক URL নিজেই একটি ক্রেডেনশিয়াল &mdash; যার কাছে এটি আছে সে আপনার চ্যানেলে পোস্ট করতে পারে &mdash; আর সাইনিং সিক্রেট প্রমাণ করে যে বার্তাটি সত্যিই আপনার কাছ থেকে এসেছে।',
