        'enc_off_body' => 'এনক্রিপশন কী ফাইল থাকলে FreeITSM এগুলো এনক্রিপ্ট করে, কিন্তু এই ইনস্টলে তা নেই, তাই আপনার ওয়েবহুক পুরোপুরি ব্যর্থ করার বদলে এগুলো যেমন আছে তেমনই সংরক্ষিত হচ্ছে। যে-কেউ ডেটাবেস বা তার ব্যাকআপ পড়তে পারে সে আপনার চ্যানেলে পোস্ট করতে এবং আপনার সিগনেচার জাল করতে পারে। এনক্রিপশন কী (<code>ENCRYPTION_KEY_PATH</code>) কনফিগার করুন এবং সংরক্ষিত মানগুলো এনক্রিপ্ট করতে প্রতিটি ওয়েবহুক ওয়ার্কফ্লো আবার সংরক্ষণ করুন।',
