        'ret_help' => 'ডেলিভারি লগে হুবহু পাঠানো পেলোড সংরক্ষিত হয়। <strong>Full record</strong> ফরম্যাটে সেটি একটি <strong>পুরো টিকিট</strong> &mdash; বিষয়, অনুরোধকারী, সবকিছু &mdash; সাধারণ টেক্সটে এখানে কপি করা থাকে। এই কয়দিন পর পেলোড ও প্রতিক্রিয়ার বডি মুছে ফেলা হয়, আর ডেলিভারি <em>রেকর্ড</em> (এন্ডপয়েন্ট, স্ট্যাটাস, সময়, ত্রুটি) অডিটের জন্য রাখা হয় যতক্ষণ না উপরের লগ সংরক্ষণকাল ({days} দিন) সারিটি পুরোপুরি সরিয়ে দেয়।',
